package dev.zomboid.gore;import java.util.*;import net.minecraft.world.item.ItemStack;
public class CollectChecks{static int n;static void check(boolean b){if(!b)throw new AssertionError(n);n++;}static ItemStack stack(String k,int c){return new ItemStack(k,c,64);}public static class Container{public List<Object> slots;Container(List<Object> s){slots=s;}public int getContainerSize(){return slots.size();}public Object getItem(int i){return slots.get(i);}public void setItem(int i,Object s){slots.set(i,s);}public int getMaxStackSize(){return 64;}}
public static class Level{public List<net.minecraft.world.entity.item.ItemEntity> items=new ArrayList<>();public boolean blocked;public List<?> getEntitiesOfClass(Class<?> c,Object box,java.util.function.Predicate<Object> filter){return items.stream().filter(filter).toList();}public Hit clip(Object ctx){return new Hit(blocked);}}
public static class Hit{boolean blocked;Hit(boolean b){blocked=b;}public String getType(){return blocked?"BLOCK":"MISS";}public Object getBlockPos(){return new net.minecraft.core.BlockPos(5,0,5);}}
public static void main(String[]args){ItemStack existing=stack("ammo:tagA",60),drop=stack("ammo:tagA",10);List<Object> slots=new ArrayList<>(List.of(existing,stack("",0)));CorpseCollect.insert(drop,slots,null);check(drop.count==0);check(((ItemStack)slots.get(0)).count==64);check(((ItemStack)slots.get(1)).count==6);check(existing.count==60);ItemStack other=stack("ammo:tagB",8);CorpseCollect.insert(other,slots,null);check(other.count==8);check(((ItemStack)slots.get(1)).key.equals("ammo:tagA"));ItemStack excess=stack("ammo:tagA",100);CorpseCollect.insert(excess,slots,null);check(excess.count==42);check(((ItemStack)slots.get(1)).count==64);List<Object> small=new ArrayList<>(List.of(new ItemStack("",0,1)));ItemStack tool=new ItemStack("gun:nbt",1,1);CorpseCollect.insert(tool,null,new Container(small));check(tool.count==0);check(((ItemStack)small.get(0)).key.equals("gun:nbt"));ItemStack second=new ItemStack("gun:nbt",1,1);CorpseCollect.insert(second,null,new Container(small));check(second.count==1);ItemStack untouched=stack("x",15);CorpseCollect.insert(untouched,new ArrayList<>(),null);check(untouched.count==15);List<Object> growing=new ArrayList<>();ItemStack many=stack("ammo:custom",150);CorpseCollect.insertGrowing(many,growing);check(many.count==0);check(growing.size()==3);check(((ItemStack)growing.get(2)).count==22);ItemStack diff=stack("ammo:different",5);CorpseCollect.insertGrowing(diff,growing);check(growing.size()==4);check(((ItemStack)growing.get(3)).key.equals("ammo:different"));Level level=new Level();net.minecraft.core.BlockPos pos=new net.minecraft.core.BlockPos(0,0,0);List<Object> fixed=new ArrayList<>(List.of(stack("a",60)));var item=new net.minecraft.world.entity.item.ItemEntity(stack("a",10));level.items.add(item);check(CorpseCollect.collect(level,pos,fixed,null,null)==1);check(item.stack.count==6&&!item.discarded);check(((ItemStack)fixed.get(0)).count==64);List<Object> extra=new ArrayList<>();check(CorpseCollect.collect(level,pos,fixed,null,extra)==1);check(item.discarded&&((ItemStack)extra.get(0)).count==6);item=new net.minecraft.world.entity.item.ItemEntity(stack("new",10));level.items.clear();level.items.add(item);level.blocked=true;check(CorpseCollect.collect(level,pos,fixed,null,extra)==0);check(!item.discarded);level.blocked=false;item.x=5;check(CorpseCollect.collect(level,pos,fixed,null,extra)==0);item.x=.7;item.y=2;check(CorpseCollect.collect(level,pos,fixed,null,extra)==0);item.y=.2;item.tickCount=50;check(CorpseCollect.collect(level,pos,fixed,null,extra)==0);System.out.println("Corpse inventory conservation checks: "+n);}}
